CREATE TABLE "USER" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" TEXT NOT NULL, "isEmailVerified" BOOLEAN NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "USER_pkey" PRIMARY KEY ("id"));
CREATE TABLE "VERIFICATION_CODE" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "codeHash" TEXT NOT NULL, "expiresAt" TIMESTAMPTZ(3) NOT NULL, "usedAt" TIMESTAMPTZ(3), "invalidatedAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "VERIFICATION_CODE_pkey" PRIMARY KEY ("id"));
CREATE TABLE "REFRESH_TOKEN" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMPTZ(3) NOT NULL, "revokedAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "REFRESH_TOKEN_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FOLDER" ("id" UUID NOT NULL, "ownerId" UUID NOT NULL, "parentId" UUID, "name" TEXT NOT NULL, "deletedAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "FOLDER_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FILE" ("id" UUID NOT NULL, "ownerId" UUID NOT NULL, "folderId" UUID, "originalName" TEXT NOT NULL, "storageKey" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "size" BIGINT NOT NULL, "extractedContent" TEXT, "deletedAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "FILE_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AUDIT_LOG" ("id" UUID NOT NULL, "actorId" UUID, "action" TEXT NOT NULL, "entityType" TEXT, "entityId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "AUDIT_LOG_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "USER_email_key" ON "USER"("email");
ALTER TABLE "VERIFICATION_CODE" ADD CONSTRAINT "VERIFICATION_CODE_userId_fkey" FOREIGN KEY ("userId") REFERENCES "USER"("id") ON DELETE NO ACTION ON UPDATE CASCADE;
ALTER TABLE "REFRESH_TOKEN" ADD CONSTRAINT "REFRESH_TOKEN_userId_fkey" FOREIGN KEY ("userId") REFERENCES "USER"("id") ON DELETE NO ACTION ON UPDATE CASCADE;
ALTER TABLE "FOLDER" ADD CONSTRAINT "FOLDER_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "USER"("id") ON DELETE NO ACTION ON UPDATE CASCADE;
ALTER TABLE "FOLDER" ADD CONSTRAINT "FOLDER_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "FOLDER"("id") ON DELETE NO ACTION ON UPDATE CASCADE;
ALTER TABLE "FILE" ADD CONSTRAINT "FILE_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "USER"("id") ON DELETE NO ACTION ON UPDATE CASCADE;
ALTER TABLE "FILE" ADD CONSTRAINT "FILE_folderId_fkey" FOREIGN KEY ("folderId") REFERENCES "FOLDER"("id") ON DELETE NO ACTION ON UPDATE CASCADE;
ALTER TABLE "AUDIT_LOG" ADD CONSTRAINT "AUDIT_LOG_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "USER"("id") ON DELETE NO ACTION ON UPDATE CASCADE;
